content.solution_code:
class MysticPotion {
  #purityLevel;
  #isCursed;

  constructor(initialPurity) {
    this.#purityLevel = initialPurity;
    this.#isCursed = false;
  }

  consume() {
    this.#purityLevel -= 10;
    if (this.#purityLevel <= 0) {
      this.#isCursed = true;
      return "A chilling sensation takes over... The potion is now cursed!";
    }
    if (this.#isCursed) {
      return "The curse deepens as you consume more.";
    }
    return "You feel a faint warmth spreading through you.";
  }

  purify() {
    this.#purityLevel += 20;
    if (this.#isCursed) {
      this.#isCursed = false;
      return "The dark aura recedes. The potion is no longer cursed.";
    }
    return "The potion shimmers with renewed energy.";
  }

  describe() {
    if (this.#isCursed) {
      return "A dark, ominous potion, radiating ill will.";
    } else if (this.#purityLevel > 50) {
      return "A shimmering potion, full of potential.";
    } else if (this.#purityLevel > 0) {
      return "A slightly murky potion, but still safe to drink.";
    } else {
      return "An inert, useless sludge.";
    }
  }
}

